 useEffect(()=>{const params=new URLSearchParams(window.location.search);if(params.get('payment')!=='success'||!params.get('session_id'))return;let cancelled=false;setEbookBusy(true);setEbookNotice('Paiement reçu. Vérification et préparation du téléchargement…');(async()=>{try{if(!supabase)throw new Error('Service de livraison non configuré. Contactez le studio.');const {data:result,error}=await supabase.functions.invoke('download-ebook',{body:{session_id:params.get('session_id')}});if(error||!result?.url)throw new Error(result?.error||error?.message||'Téléchargement momentanément indisponible.');if(!cancelled)window.location.assign(result.url);}catch(err){if(!cancelled)setEbookNotice(err?.message||'Téléchargement momentanément indisponible.');}finally{if(!cancelled)setEbookBusy(false)}})();return()=>{cancelled=true}},[]);
 useEffect(()=>{const title=data.brand.replace('THOMAS','Thomas').replace('CAMILLE','Camille')+' — Studio de contenu';document.title=title;const setMeta=(property,content)=>{let node=document.querySelector('meta[property="'+property+'"]');if(!node){node=document.createElement('meta');node.setAttribute('property',property);document.head.appendChild(node)}node.setAttribute('content',content||'')};setMeta('og:title',title);setMeta('og:description',data.intro);setMeta('og:image',data.ogImage);let icon=document.querySelector('link[rel~="icon"]');if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.appendChild(icon)}if(data.faviconImage)icon.href=data.faviconImage;},[data.brand,data.intro,data.ogImage,data.faviconImage]);
 useEffect(()=>{if(!supabase){setAuthLoading(false);return;}let cancelled=false;supabase.auth.getSession().then(({data,error})=>{if(!cancelled){setSession(data?.session||null);setAuthLoading(false);if(error)setAuthError(error.message)}});const {data:{subscription}}=supabase.auth.onAuthStateChange((event,nextSession)=>{setSession(nextSession);if(event==='PASSWORD_RECOVERY'){setAdmin(true);setPasswordSetupRequired(true);setAuthError('')}});supabase.from('site_settings').select('settings').eq('id','main').maybeSingle().then(({data,error})=>{if(cancelled)return;if(data?.settings)setData({...initial,...data.settings});if(error)setNotice('Impossible de charger la configuration distante. Vérifiez la migration Supabase et les droits de lecture.');});return()=>{cancelled=true;subscription.unsubscribe()}},[]);
 const change=(key,value)=>{setData(prev=>({...prev,[key]:value}));setSaved(false)};
 const save=async()=>{if(supabase){if(!isAdmin){setNotice('Connexion administrateur requise pour enregistrer.');return;}const {error}=await supabase.from('site_settings').upsert({id:'main',settings:data,updated_at:new Date().toISOString()});if(error){setNotice('Enregistrement distant impossible : '+error.message);return;}setSaved(true);setNotice('Modifications publiées et enregistrées.');return;}try{localStorage.setItem('txc-settings',JSON.stringify(data));setSaved(true);setNotice('Enregistré uniquement dans ce navigateur. Configurez Supabase pour publier les modifications pour tous.');}catch{setNotice('Stockage plein : privilégiez des images hébergées et leurs URL.')}};
 const login=async(e)=>{e.preventDefault();setAuthError('');if(!supabase){setAuthError('Supabase n’est pas configuré.');return;}const {data,error}=await supabase.auth.signInWithPassword({email:loginEmail,password:loginPassword});if(error){setAuthError('Connexion impossible : '+error.message);return;}if(data?.user?.app_metadata?.must_change_password)setPasswordSetupRequired(true)};
 const requestPasswordReset=async()=>{if(passwordResetBusy||passwordResetCooldown>0)return;setAuthError('');setPasswordResetSent(false);const email=loginEmail.trim().toLowerCase();if(!email){setAuthError('Saisissez d’abord votre adresse e-mail.');return;}if(!supabase){setAuthError('Service de connexion indisponible.');return;}setPasswordResetBusy(true);const until=Date.now()+60000;sessionStorage.setItem('txc-password-reset-until',String(until));setPasswordResetCooldown(60);try{const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:'https://thomasitoui.github.io/Thomas-xCamille/?auth=recovery#admin'});if(error)throw error;setPasswordResetSent(true)}catch(error){const message=error?.message||'';if(/after\s+\d+\s+seconds|security purposes|rate limit|too many requests/i.test(message)){setAuthError('Une demande vient déjà d’être effectuée. Pour protéger votre compte, patientez avant de réessayer.');}else{setAuthError('Envoi du lien impossible : '+(message||'erreur inconnue'));}}finally{setPasswordResetBusy(false)}};
 const setAdminPassword=async(e)=>{e.preventDefault();setAuthError('');if(!supabase||!session){setAuthError('La session d’invitation est absente ou expirée. Demandez un nouvel e-mail d’invitation.');return;}if(newAdminPassword.length<10){setAuthError('Choisissez un mot de passe de 10 caractères minimum.');return;}if(newAdminPassword!==confirmAdminPassword){setAuthError('Les deux mots de passe ne correspondent pas.');return;}setPasswordSetupBusy(true);try{const {error}=await supabase.auth.updateUser({password:newAdminPassword});if(error)throw error;const {data:clearResult,error:clearError}=await supabase.functions.invoke('clear-temp-password');if(clearError||!clearResult?.success)throw new Error(clearResult?.error||clearError?.message||'Impossible de finaliser la sécurisation du compte.');setPasswordSetupRequired(false);setNewAdminPassword('');setConfirmAdminPassword('');window.history.replaceState(null,'',window.location.pathname+window.location.search+'#admin');setAdmin(true)}catch(error){setAuthError('Impossible de définir le mot de passe : '+(error?.message||'erreur inconnue'))}finally{setPasswordSetupBusy(false)}};
 const logout=async()=>{if(supabase)await supabase.auth.signOut();setSession(null);setPasswordSetupRequired(false)};
 const createAdminAccount=async(e)=>{e.preventDefault();setNotice('');if(!supabase||!isAdmin){setNotice('Une session administrateur est requise.');return;}const email=adminCreateEmail.trim().toLowerCase();if(!email){setNotice('Renseignez une adresse e-mail.');return;}setAdminCreateBusy(true);try{const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%';const bytes=new Uint8Array(20);crypto.getRandomValues(bytes);const password=Array.from(bytes,b=>alphabet[b%alphabet.length]).join('');const {data:result,error}=await supabase.functions.invoke('create-admin-account',{body:{email,password}});if(error){let detail='';try{const response=error.context;if(response&&typeof response.clone==='function'){const payload=await response.clone().json();detail=payload?.error||payload?.message||'';}}catch{}throw new Error(detail||result?.error||error.message||'Erreur inconnue');}if(!result?.success)throw new Error(result?.error||'Le compte n’a pas été créé.');setAdminCreateEmail('');setAdminCreatePassword(password);setNotice('Compte administrateur créé pour '+email+'. Transmettez le mot de passe temporaire de façon sécurisée. Il devra le remplacer à sa première connexion.');await loadTeam();}catch(err){setNotice('Création du compte impossible : '+(err?.message||'erreur inconnue'));}finally{setAdminCreateBusy(false)}};
 const inviteAdmin=async(e)=>{e.preventDefault();setNotice('');if(!supabase||!isAdmin){setNotice('Une session administrateur est requise.');return;}const email=adminInviteEmail.trim().toLowerCase();if(!email){setNotice('Renseignez une adresse e-mail.');return;}setAdminInviteBusy(true);try{const {data:result,error}=await supabase.functions.invoke('invite-admin',{body:{email}});if(error){let detail='';try{const response=error.context;if(response&&typeof response.clone==='function'){const payload=await response.clone().json();detail=payload?.error||payload?.message||'';}}catch{}if(!detail&&result?.error)detail=result.error;if(!detail)detail=error.message||'Erreur inconnue';throw new Error(detail);}if(!result?.success)throw new Error(result?.error||'Le serveur n’a pas confirmé l’envoi de l’invitation.');setAdminInviteEmail('');setNotice(result.existing?'Le compte '+email+' existe déjà. Ses droits administrateur sont activés. Camille peut maintenant se connecter depuis le site avec son mot de passe habituel.':'Invitation envoyée à '+email+'. Le lien renvoie désormais vers le site en ligne. Vérifiez la boîte de réception et les courriers indésirables.');}catch(err){const detail=err?.message||'Erreur inconnue';const duplicate=/already registered|already been registered|user.*exists|already invited/i.test(detail);setNotice(duplicate?'Cette adresse possède déjà un compte ou une invitation. Demandez à votre collègue de vérifier ses e-mails ou de se connecter avec son compte existant. Détail : '+detail:'Invitation impossible : '+detail);}finally{setAdminInviteBusy(false)}};
 const removeAdmin=async(member)=>{if(!supabase||!isAdmin||!member?.user_id)return;if(member.user_id===session?.user?.id){setNotice('Vous ne pouvez pas supprimer votre propre accès.');return;}if(!window.confirm('Supprimer définitivement le compte administrateur de '+member.email+' ? Cette action supprime son compte Supabase Auth et ne peut pas être annulée.'))return;setNotice('');setTeamLoading(true);try{const {data:result,error}=await supabase.functions.invoke('remove-admin',{body:{user_id:member.user_id}});if(error){let detail='';try{const response=error.context;if(response&&typeof response.clone==='function'){const payload=await response.clone().json();detail=payload?.error||payload?.message||'';}}catch{}throw new Error(detail||result?.error||error.message||'Erreur inconnue');}if(!result?.success)throw new Error(result?.error||'Le serveur n’a pas confirmé le retrait.');setTeamMembers(prev=>prev.filter(item=>item.user_id!==member.user_id));setNotice('Le compte administrateur de '+member.email+' a été supprimé définitivement.');}catch(err){setNotice('Suppression impossible : '+(err?.message||'erreur inconnue'));}finally{setTeamLoading(false)}};
